const isLight = (c:string) => ["#ffffff","#f8fafc","#f7fee7","#fff7ed","#f8f3e8","#f5f5f4"].includes(c);

function coreLayout(prefix:string,s:Spec,pageNo:number):PublisherElement[]{
  const {width:W,height:H}=s; const [bg,accent,paper,muted]=s.palette; const ink=isLight(bg)?"#111827":paper; const sub=isLight(bg)?muted:paper;
  const e:PublisherElement[]=[rect(`${prefix}-bg`,0,0,W,H,bg)]; const l=s.layout;
  const pad=Math.max(24,Math.round(Math.min(W,H)*.055));
  switch(l){
    case 1:e.push(rect(`${prefix}-rail`,0,0,Math.max(14,W*.035),H,accent),image(`${prefix}-photo`,s.photo,W*.68,0,W*.32,H,{opacity:.92}));break;
    case 2:e.push(rect(`${prefix}-frame`,pad*.5,pad*.5,W-pad,H-pad,"transparent",{borderColor:accent,borderWidth:Math.max(1,W/500)}),circle(`${prefix}-seal`,W*.76,H*.16,Math.min(W,H)*.17,Math.min(W,H)*.17,accent));break;
    case 3:e.push(rect(`${prefix}-diag`,W*.7,-H*.2,W*.36,H*1.4,accent,{rotation:12}),rect(`${prefix}-split`,W*.64,0,W*.012,H,paper,{opacity:.7}));break;
    case 4:e.push(rect(`${prefix}-rule`,pad,H*.18,W-pad*2,Math.max(1,H*.002),muted),rect(`${prefix}-accent`,pad,H*.78,W*.22,Math.max(4,H*.008),accent));break;
    case 5:e.push(rect(`${prefix}-frame`,pad,pad,W-pad*2,H-pad*2,"transparent",{borderColor:accent,borderWidth:2}),circle(`${prefix}-mono`,W*.76,H*.2,Math.min(W,H)*.18,Math.min(W,H)*.18,accent));break;
    case 6:e.push(rect(`${prefix}-block1`,0,0,W*.34,H,accent),rect(`${prefix}-block2`,W*.34,0,W*.1,H,paper),circle(`${prefix}-dot`,W*.83,H*.12,Math.min(W,H)*.1,Math.min(W,H)*.1,accent));break;
    case 7:e.push(image(`${prefix}-photo`,s.photo,0,0,W*.42,H),rect(`${prefix}-shade`,0,0,W*.42,H,"#000000",{opacity:.24}),rect(`${prefix}-line`,W*.42,0,W*.012,H,accent));break;
    case 8:e.push(rect(`${prefix}-offset`,W*.62,H*.08,W*.3,H*.82,accent),rect(`${prefix}-window`,W*.67,H*.13,W*.3,H*.66,paper),image(`${prefix}-photo`,s.photo,W*.68,H*.14,W*.28,H*.64));break;
    case 9:e.push(circle(`${prefix}-g1`,W*.62,-H*.18,Math.min(W,H)*.55,Math.min(W,H)*.55,accent,{opacity:.82}),circle(`${prefix}-g2`,W*.74,H*.4,Math.min(W,H)*.43,Math.min(W,H)*.43,paper,{opacity:.45}),rect(`${prefix}-slash`,W*.69,0,W*.018,H,paper,{rotation:-9,opacity:.7}));break;
    case 10:e.push(image(`${prefix}-photo`,s.photo,W*.62,0,W*.38,H),rect(`${prefix}-caption`,W*.56,H*.68,W*.44,H*.32,accent),rect(`${prefix}-top`,pad,pad,W*.25,Math.max(4,H*.008),accent));break;
    case 11:e.push(image(`${prefix}-photo`,s.photo,0,0,W*.46,H),rect(`${prefix}-overlay`,0,0,W*.46,H,"#000000",{opacity:.28}),rect(`${prefix}-gold`,W*.46,0,W*.014,H,accent));break;
    case 12:e.push(rect(`${prefix}-crest`,W*.73,H*.14,W*.18,H*.32,accent,{borderRadius:4}),text(`${prefix}-crest-text`,s.kind.toUpperCase().slice(0,4),W*.75,H*.24,W*.14,H*.1,Math.max(12,H*.032),bg,"900",{textAlign:"center",fontFamily:s.fonts[0]}),rect(`${prefix}-rule`,pad,H*.68,W*.56,1,accent));break;
    case 13:e.push(circle(`${prefix}-symbol`,W*.74,H*.13,Math.min(W,H)*.2,Math.min(W,H)*.2,accent),text(`${prefix}-plus`,"+",W*.775,H*.155,W*.11,H*.12,Math.max(20,H*.06),paper,"900",{textAlign:"center"}),rect(`${prefix}-band`,0,H*.82,W,H*.18,paper));break;
    case 14:e.push(image(`${prefix}-photo`,s.photo,0,0,W,H*.34),rect(`${prefix}-shade`,0,0,W,H*.34,"#000000",{opacity:.3}),rect(`${prefix}-line`,pad,H*.62,W*.46,2,accent));break;
    case 15:e.push(rect(`${prefix}-bar`,0,0,W,H*.1,accent),rect(`${prefix}-angle`,W*.7,H*.1,W*.3,H*.9,muted),image(`${prefix}-photo`,s.photo,W*.73,H*.14,W*.24,H*.82));break;
    case 16:e.push(rect(`${prefix}-frame`,pad*.5,pad*.5,W-pad,H-pad,"transparent",{borderColor:accent,borderWidth:1}),rect(`${prefix}-frame2`,pad*.8,pad*.8,W-pad*1.6,H-pad*1.6,"transparent",{borderColor:accent,borderWidth:.5}),circle(`${prefix}-seal`,W*.43,H*.16,Math.min(W,H)*.17,Math.min(W,H)*.17,accent));break;
    case 17:e.push(circle(`${prefix}-halo`,W*.7,H*.1,Math.min(W,H)*.28,Math.min(W,H)*.28,paper),image(`${prefix}-photo`,s.photo,W*.72,H*.12,Math.min(W,H)*.24,Math.min(W,H)*.24,{borderRadius:Math.min(W,H)*.12}),rect(`${prefix}-rule`,pad,H*.7,W-pad*2,1,accent));break;
    case 18:e.push(image(`${prefix}-photo`,s.photo,0,0,W,H,{opacity:.35}),rect(`${prefix}-panel`,pad,H*.08,W-pad*2,H*.84,paper,{opacity:.94}),rect(`${prefix}-line`,pad*1.6,H*.16,W*.012,H*.58,accent));break;
    case 19:e.push(...[.68,.78,.88].map((x,i)=>rect(`${prefix}-grid-${i}`,W*x,0,1,H,accent,{opacity:.42})),circle(`${prefix}-node`,W*.73,H*.22,Math.min(W,H)*.04,Math.min(W,H)*.04,accent),circle(`${prefix}-node2`,W*.83,H*.62,Math.min(W,H)*.04,Math.min(W,H)*.04,accent));break;
    case 20:e.push(rect(`${prefix}-shape1`,W*.64,0,W*.36,H*.32,accent),rect(`${prefix}-shape2`,W*.76,H*.32,W*.24,H*.68,muted),rect(`${prefix}-shape3`,W*.64,H*.68,W*.12,H*.32,ink),image(`${prefix}-photo`,s.photo,W*.68,H*.08,W*.27,H*.48,{opacity:.76}));break;
  }
  // Category-specific structural motif keeps all 320 compositions distinct, beyond palette changes.
  const motifX=W*(0.08+((s.categoryIndex*7)%13)*0.025); const motifY=H*(0.06+((s.categoryIndex*5)%9)*0.025);
  for(let m=0;m<(s.categoryIndex%4)+1;m++) e.push(rect(`${prefix}-category-motif-${m}`,motifX+m*W*.018,motifY+m*H*.012,W*(.006+(s.categoryIndex%3)*.002),H*(.06+(m%2)*.025),accent,{opacity:.55}));
  const hasPrimaryPhoto=[1,7,8,10,11,14,15,17,18,20].includes(l);
  if(!hasPrimaryPhoto) e.push(image(`${prefix}-photo-placeholder`,s.photo,W*.82,H*.72,W*.13,H*.17,{opacity:.82,borderRadius:Math.max(2,Math.min(W,H)*.008)}));
  const left=[6,7,11,14].includes(l)?W*.48:pad; const avail=[6,7,11,14].includes(l)?W*.46:([1,8,10,15,18,20].includes(l)?W*.56:W*.62);
  const top=l===14?H*.42:H*.25;
  e.push(text(`${prefix}-kicker`,s.subcategory.toUpperCase(),left,l===14?H*.37:pad,avail,H*.05,Math.max(8,H*.018),accent,"900",{letterSpacing:1.8,fontFamily:s.fonts[1]}));
  e.push(text(`${prefix}-title`,s.name.toUpperCase(),left,top,avail,H*.2,Math.max(20,Math.min(54,H*.055)),ink,"900",{fontFamily:s.fonts[0],lineHeight:Math.max(24,Math.min(60,H*.064))}));
  e.push(text(`${prefix}-subtitle`,contentFor(s,pageNo),left,top+H*.21,avail,H*.18,Math.max(10,H*.021),sub,"600",{fontFamily:s.fonts[1],lineHeight:Math.max(14,H*.03)}));
  e.push(text(`${prefix}-footer`,`YAPOSAN DESIGN STUDIO  •  FULLY EDITABLE  •  ${s.pageSize.toUpperCase()}`,left,H*.88,avail,H*.05,Math.max(7,H*.014),ink,"700",{fontFamily:s.fonts[1],letterSpacing:.7}));
  return e;
}

